const SKIP: i32 = 77;
const S_OK: i32 = 0;
const OPEN_FAILED: i32 = -5;

#[derive(Debug)]
enum FixtureError {
    Skip(&'static str, i32),
    Fail(&'static str),
}

fn require(condition: bool, label: &'static str) -> Result<(), FixtureError> {
    if condition {
        Ok(())
    } else {
        Err(FixtureError::Fail(label))
    }
}

unsafe extern "C" fn log(_: *mut c_void, line: *const c_char) {
    eprintln!("  {}", unsafe { CStr::from_ptr(line) }.to_string_lossy());
}

struct Surface(*mut rsf_shared_surface);
impl Drop for Surface {
    fn drop(&mut self) {
        unsafe { rsf_shared_surface_destroy(self.0) };
    }
}

struct Fence(*mut rsf_shared_fence);
impl Drop for Fence {
    fn drop(&mut self) {
        unsafe { rsf_shared_fence_destroy(self.0) };
    }
}

fn create_d3d11() -> Result<(ID3D11Device, ID3D11DeviceContext), FixtureError> {
    let levels = [D3D_FEATURE_LEVEL_11_1, D3D_FEATURE_LEVEL_11_0];
    let create =
        |driver| rsf_test_support::d3d11_device(driver, D3D11_CREATE_DEVICE_FLAG(0), Some(&levels));
    create(D3D_DRIVER_TYPE_HARDWARE)
        .or_else(|_| create(D3D_DRIVER_TYPE_WARP))
        .map_err(|error| FixtureError::Skip("no D3D11 device", error.code().0))
}

fn create_d3d12(device11: &ID3D11Device) -> Result<ID3D12Device, FixtureError> {
    // Match the actual adapter selected by D3D11 even on multi-adapter systems.
    let adapter = device11
        .cast::<IDXGIDevice>()
        .and_then(|device| unsafe { device.GetAdapter() })
        .and_then(|adapter| adapter.cast::<IUnknown>())
        .map_err(|error| {
            FixtureError::Skip("no DXGI adapter for the D3D11 device", error.code().0)
        })?;
    rsf_test_support::d3d12_device(&adapter)
        .map_err(|error| FixtureError::Skip("no D3D12 device on the D3D11 adapter", error.code().0))
}

fn surface_checks(device11: *mut c_void, device12: *mut c_void) -> Result<(), FixtureError> {
    let mut setup = rsf_shared_surface_setup {
        struct_size: size_of::<rsf_shared_surface_setup>() as u32,
        abi_version: RSF_SHARED_SURFACE_ABI_VERSION,
        width: 64,
        height: 32,
        format: DXGI_FORMAT_R8G8B8A8_UNORM.0 as u32,
        render_target: 1,
        log: Some(log),
        log_user: null_mut(),
        unordered_access: 0,
    };

    eprintln!("[stage] D3D11 exports a shared NT handle");
    let mut shared = Surface(null_mut());
    let result = unsafe { rsf_shared_surface_create(device11, null_mut(), &setup, &mut shared.0) };
    if result != S_OK {
        return Err(FixtureError::Skip(
            "D3D11 could not export a shared NT handle",
            result,
        ));
    }
    require(
        !unsafe { rsf_shared_surface_d3d11(shared.0) }.is_null(),
        "D3D11 texture",
    )?;
    require(
        !unsafe { rsf_shared_surface_target(shared.0) }.is_null(),
        "D3D11 render target",
    )?;
    require(
        unsafe { rsf_shared_surface_d3d12(shared.0) }.is_null(),
        "no D3D12 device means no opened resource",
    )?;
    drop(shared);

    eprintln!("[stage] D3D12 opens the same resource");
    let mut shared = Surface(null_mut());
    let result = unsafe { rsf_shared_surface_create(device11, device12, &setup, &mut shared.0) };
    if result == OPEN_FAILED {
        return Err(FixtureError::Skip(
            "D3D12 could not open the shared NT handle",
            result,
        ));
    }
    require(result == S_OK, "shared resource creation")?;
    let resource = unsafe { rsf_shared_surface_d3d12(shared.0) };
    let Some(resource) = (unsafe { ID3D12Resource::from_raw_borrowed(&resource) }) else {
        return Err(FixtureError::Fail("D3D12 resource"));
    };
    let desc = unsafe { resource.GetDesc() };
    require(
        desc.Width == 64 && desc.Height == 32,
        "D3D12 resource extent",
    )?;
    require(
        desc.Format == DXGI_FORMAT_R8G8B8A8_UNORM,
        "D3D12 resource format",
    )?;
    drop(shared);

    eprintln!("[stage] shared surface argument validation");
    let mut output = Surface(null_mut());
    setup.format = DXGI_FORMAT_R8G8B8A8_TYPELESS.0 as u32;
    require(
        unsafe { rsf_shared_surface_create(device11, device12, &setup, &mut output.0) }
            == INVALID_ARGUMENT,
        "typeless format must be refused",
    )?;
    setup.format = DXGI_FORMAT_R8G8B8A8_UNORM.0 as u32;
    setup.abi_version += 1;
    require(
        unsafe { rsf_shared_surface_create(device11, device12, &setup, &mut output.0) }
            == ABI_MISMATCH,
        "ABI mismatch must be refused",
    )?;
    setup.abi_version = RSF_SHARED_SURFACE_ABI_VERSION;
    setup.width = 0;
    require(
        unsafe { rsf_shared_surface_create(device11, device12, &setup, &mut output.0) }
            == INVALID_ARGUMENT,
        "empty extent must be refused",
    )?;
    require(
        unsafe { rsf_shared_surface_create(null_mut(), device12, &setup, &mut output.0) }
            == INVALID_ARGUMENT,
        "null device must be refused",
    )?;
    unsafe {
        rsf_shared_surface_destroy(null_mut());
        rsf_shared_fence_destroy(null_mut());
    }
    Ok(())
}

fn fence_checks(
    device11: &ID3D11Device,
    device12: &ID3D12Device,
    context: ID3D11DeviceContext,
) -> Result<(), FixtureError> {
    eprintln!("[stage] D3D11 signals a fence opened by D3D12");
    let mut fence = Fence(null_mut());
    let result = unsafe {
        rsf_shared_fence_create(
            device11.as_raw(),
            device12.as_raw(),
            Some(log),
            null_mut(),
            &mut fence.0,
        )
    };
    if result != S_OK {
        return Err(FixtureError::Skip(
            "the devices could not share a fence",
            result,
        ));
    }
    let raw11 = unsafe { rsf_shared_fence_d3d11(fence.0) };
    let raw12 = unsafe { rsf_shared_fence_d3d12(fence.0) };
    let (Some(fence11), Some(fence12)) =
        (unsafe { ID3D11Fence::from_raw_borrowed(&raw11) }, unsafe {
            ID3D12Fence::from_raw_borrowed(&raw12)
        })
    else {
        return Err(FixtureError::Fail("both fence views must exist"));
    };
    let Ok(context) = context.cast::<ID3D11DeviceContext4>() else {
        eprintln!("  no ID3D11DeviceContext4, so the signal round trip is untested");
        return Ok(());
    };
    require(
        unsafe { context.Signal(fence11, 7) }.is_ok(),
        "D3D11 fence signal",
    )?;
    unsafe { context.Flush() };
    for _ in 0..100 {
        if unsafe { fence12.GetCompletedValue() } >= 7 {
            return Ok(());
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    require(
        unsafe { fence12.GetCompletedValue() } >= 7,
        "D3D12 must observe the D3D11 signal",
    )
}

fn run() -> Result<(), FixtureError> {
    eprintln!("[stage] create D3D11 device");
    let (device11, context) = create_d3d11()?;
    eprintln!("[stage] create D3D12 device on the same adapter");
    let device12 = create_d3d12(&device11)?;
    surface_checks(device11.as_raw(), device12.as_raw())?;
    fence_checks(&device11, &device12, context)
}

#[unsafe(no_mangle)]
extern "C" fn rsf_shared_surface_fixture() -> i32 {
    match run() {
        Ok(()) => {
            eprintln!("shared_surface: all checks passed");
            0
        }
        Err(FixtureError::Skip(message, result)) => {
            eprintln!(
                "shared_surface: {message} (result 0x{:08x}), skipping",
                result as u32
            );
            SKIP
        }
        Err(FixtureError::Fail(message)) => {
            eprintln!("shared_surface: FAIL: {message}");
            1
        }
    }
}
